(()=>{
const rates={QAR:1,USD:.274725,EUR:.2345,GBP:.2045,AED:1.0088,SAR:1.0302,KWD:.0839,BHD:.1033,OMR:.1057,TND:.812908,MAD:2.63508},symbols={QAR:'QAR',USD:'$',EUR:'€',GBP:'£',AED:'AED',SAR:'SAR',KWD:'KWD',BHD:'BHD',OMR:'OMR',TND:'TND',MAD:'MAD'};
let currency=localStorage.getItem('sultana-currency')||'QAR';if(!rates[currency])currency='QAR';
const fmt=n=>`${symbols[currency]} ${(n*rates[currency]).toLocaleString(undefined,{minimumFractionDigits:currency==='QAR'?0:2,maximumFractionDigits:2})}`;
const convertText=()=>document.querySelectorAll('.price,.detail-price,#bag-total,.cart-total,.cart-subtotal,.subtotal,.total,[data-price-display],[data-money]').forEach(el=>{if(!el.dataset.qar){const m=el.textContent.match(/QAR\s*([\d,.]+)/i);if(m)el.dataset.qar=m[1].replace(/,/g,'')}if(el.dataset.qar)el.textContent=fmt(Number(el.dataset.qar))});
const css=`@media(min-width:851px){body>header{height:160px!important;min-height:160px!important;padding:0 5%!important;display:grid!important;grid-template-columns:1fr auto 1fr!important;grid-template-rows:112px 48px!important;gap:0 24px!important;align-items:center!important;background:#fffdfa!important;position:relative!important;overflow:visible!important}body>header>.brand{display:block!important;grid-column:2!important;grid-row:1!important;justify-self:center!important;position:static!important;transform:none!important;width:92px!important;height:102px!important;margin:0!important}body>header>.brand img{display:block!important;width:100%!important;height:100%!important;object-fit:contain!important}body>header>.header-actions{grid-column:3!important;grid-row:1!important;justify-self:end!important;display:flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;gap:18px!important;position:static!important;z-index:10001!important}body>header>.header-actions .icon-button{display:inline-flex!important;visibility:visible!important;opacity:1!important;position:relative!important;width:38px!important;height:38px!important;align-items:center!important;justify-content:center!important;padding:6px!important;color:#17130f!important}body>header>.header-actions svg{display:block!important;width:24px!important;height:24px!important}.header-bag-count{position:absolute!important;top:0!important;right:-3px!important;min-width:15px!important;height:15px!important;background:#17130f!important;color:#fff!important;font:10px/15px Arial,sans-serif!important;text-align:center!important}body>header>#main-navigation,body>header>.menu-toggle{display:none!important}body>header>.desktop-header-left{grid-column:1!important;grid-row:1!important;justify-self:start!important;display:flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;gap:11px!important;font-size:12px!important;white-space:nowrap!important}body>header>.desktop-header-left select,body>header>.desktop-header-left a{border:0!important;background:transparent!important;padding:4px 0!important;font-size:12px!important;color:#17130f!important;text-decoration:none!important}body>header>.desktop-header-left .sep{color:#9b9286!important}body>header>nav.desktop-luxury-nav{grid-column:1/-1!important;grid-row:2!important;display:flex!important;visibility:visible!important;opacity:1!important;position:relative!important;inset:auto!important;transform:none!important;width:100%!important;height:48px!important;min-height:48px!important;align-items:center!important;justify-content:center!important;gap:clamp(25px,3vw,52px)!important;background:#fffdfa!important;z-index:10000!important;margin:0!important;padding:0 20px!important;overflow:visible!important}body>header>nav.desktop-luxury-nav>a{display:inline-flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;height:48px!important;color:#17130f!important;font:500 11px/48px Arial,sans-serif!important;letter-spacing:.35px!important;text-transform:uppercase!important;white-space:nowrap!important;text-decoration:none!important;margin:0!important;padding:0!important}}
.sultana-service-strip{width:100%;display:grid;grid-template-columns:repeat(5,1fr);background:#fffdfa;border-top:1px solid #e8dfd2;border-bottom:1px solid #e8dfd2;color:#211b15}.sultana-service-item{min-height:112px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:15px 12px;border-right:1px solid #e8dfd2}.sultana-service-item:last-child{border-right:0}.sultana-service-icon{width:34px;height:34px;margin-bottom:7px;color:#9b7444}.sultana-service-icon svg{width:100%;height:100%;display:block;fill:none;stroke:currentColor;stroke-width:1.45;stroke-linecap:round;stroke-linejoin:round}.sultana-service-title{font:600 12px/1.25 Arial,sans-serif;text-transform:uppercase;letter-spacing:.15px}.sultana-service-sub{font:400 10px/1.35 Arial,sans-serif;color:#6e655b;margin-top:2px}
@media(max-width:850px){body>header>.desktop-luxury-nav,body>header>.desktop-header-left{display:none!important}.sultana-service-strip{grid-template-columns:repeat(2,1fr)}.sultana-service-item{min-height:105px;border-bottom:1px solid #e8dfd2}.sultana-service-item:nth-child(2n){border-right:0}.sultana-service-item:last-child{grid-column:1/-1;border-bottom:0}.sultana-service-title{font-size:11px}.sultana-service-sub{font-size:9px}}`;
function installHeader(){const h=document.querySelector('body>header');if(!h)return;let style=document.getElementById('stable-global-header');if(!style){style=document.createElement('style');style.id='stable-global-header';document.head.appendChild(style)}if(style.textContent!==css)style.textContent=css;let brand=h.querySelector(':scope>.brand');if(!brand){brand=document.createElement('a');brand.className='brand';brand.href='/';brand.innerHTML='<img src="/assets/brand/sultana-logo.png" alt="Sultana Perfumes">';h.appendChild(brand)}let left=h.querySelector(':scope>.desktop-header-left');if(!left){left=document.createElement('div');left.className='desktop-header-left';h.appendChild(left)}left.innerHTML='<select id="desktop-currency-select" aria-label="Currency"><option value="QAR">🇶🇦 QAR</option><option value="USD">🇺🇸 USD</option><option value="EUR">🇪🇺 EUR</option><option value="GBP">🇬🇧 GBP</option><option value="AED">🇦🇪 AED</option><option value="SAR">🇸🇦 SAR</option><option value="KWD">🇰🇼 KWD</option><option value="BHD">🇧🇭 BHD</option><option value="OMR">🇴🇲 OMR</option><option value="TND">🇹🇳 TND</option><option value="MAD">🇲🇦 MAD</option></select><span class="sep">|</span><a href="/ar/" lang="ar">العربية</a>';left.querySelector('select').value=currency;let actions=h.querySelector(':scope>.header-actions');if(!actions){actions=document.createElement('div');actions.className='header-actions';h.appendChild(actions)}if(!actions.querySelector('#search-open'))actions.insertAdjacentHTML('beforeend','<button class="icon-button" id="search-open" aria-label="Search fragrances"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4.5 4.5"/></svg></button>');if(!actions.querySelector('#bag-open'))actions.insertAdjacentHTML('beforeend','<button class="icon-button" id="bag-open" aria-label="Open shopping bag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5.5 8.5h13l1 12h-15l1-12Z"/><path d="M9 9V6.5a3 3 0 0 1 6 0V9"/></svg><span class="header-bag-count">0</span></button>');let nav=h.querySelector(':scope>nav.desktop-luxury-nav');if(!nav){nav=document.createElement('nav');nav.className='desktop-luxury-nav';h.appendChild(nav)}const menu='<a href="/">Home</a><a href="/shop/?collection=perfume#collection">Perfumes</a><a href="/room-sprays/">Luxury Spray</a><a href="/oud-bakhoor/">Oud &amp; Bakhoor</a><a href="/b2b/">B2B</a><a href="/our-story/">Our Story</a><a href="/contact/">Contact</a>';if(nav.innerHTML!==menu)nav.innerHTML=menu}
function installServiceStrip(){if(document.querySelector('.sultana-service-strip'))return;const footer=document.querySelector('footer');if(!footer)return;const strip=document.createElement('section');strip.className='sultana-service-strip';strip.setAttribute('aria-label','Sultana service benefits');strip.innerHTML=`<div class="sultana-service-item"><span class="sultana-service-icon"><svg viewBox="0 0 48 48"><path d="M24 5 39 13 24 42 9 13 24 5Z"/><path d="m9 13 30 0M16 13l8 29 8-29M16 13l8-8 8 8"/></svg></span><span class="sultana-service-title">Premium Quality</span><span class="sultana-service-sub">Finest ingredients</span></div><div class="sultana-service-item"><span class="sultana-service-icon"><svg viewBox="0 0 48 48"><path d="M39 7C25 8 13 15 10 30c8 3 17 0 22-7 4-5 5-11 7-16Z"/><path d="M8 40c5-12 13-19 25-25"/></svg></span><span class="sultana-service-title">Authentic Scents</span><span class="sultana-service-sub">Inspired by heritage</span></div><div class="sultana-service-item"><span class="sultana-service-icon"><svg viewBox="0 0 48 48"><path d="M7 19h34v23H7zM5 13h38v8H5zM24 13v29"/><path d="M24 13c-8 0-12-2-12-6 0-3 3-4 5-3 4 1 7 9 7 9Zm0 0c8 0 12-2 12-6 0-3-3-4-5-3-4 1-7 9-7 9Z"/></svg></span><span class="sultana-service-title">Luxury Packaging</span><span class="sultana-service-sub">For every occasion</span></div><div class="sultana-service-item"><span class="sultana-service-icon"><svg viewBox="0 0 48 48"><path d="M5 13h23v20H5zM28 20h8l7 7v6H28zM12 38a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm24 0a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM3 9h17M1 16h12"/></svg></span><span class="sultana-service-title">Fast Delivery</span><span class="sultana-service-sub">Across Qatar</span></div><div class="sultana-service-item"><span class="sultana-service-icon"><svg viewBox="0 0 48 48"><path d="M8 28v-7a16 16 0 0 1 32 0v7M8 26H5v10h7V26H8Zm32 0h3v10h-7V26h4ZM36 37c-2 4-5 6-10 6"/></svg></span><span class="sultana-service-title">Dedicated Support</span><span class="sultana-service-sub">We are here for you</span></div>`;footer.parentNode.insertBefore(strip,footer)}
const hideOld=()=>document.querySelectorAll('section').forEach(s=>{const t=(s.textContent||'').replace(/\s+/g,' ').toLowerCase();if((t.includes('explore sultana')||t.includes('discover our world'))&&t.includes('wedding')&&t.includes('hospitality'))s.style.display='none'});let repairing=false;function sync(){if(repairing)return;repairing=true;installHeader();installServiceStrip();convertText();hideOld();repairing=false}document.addEventListener('change',e=>{if(e.target.id==='desktop-currency-select'||e.target.id==='currency-select'){currency=e.target.value;localStorage.setItem('sultana-currency',currency);document.querySelectorAll('#desktop-currency-select,#currency-select').forEach(s=>s.value=currency);convertText()}});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync);else sync();window.addEventListener('load',sync);[50,150,300,600,1200,2500].forEach(ms=>setTimeout(sync,ms));const observer=new MutationObserver(muts=>{if(repairing)return;let needed=false;for(const m of muts){if(m.target===document.body||m.target.closest?.('header')||[...m.addedNodes,...m.removedNodes].some(n=>n.nodeType===1&&(n.matches?.('header,footer,.desktop-luxury-nav,.desktop-header-left,.header-actions,.sultana-service-strip')||n.querySelector?.('header,footer,.desktop-luxury-nav,.desktop-header-left,.header-actions,.sultana-service-strip')))){needed=true;break}}if(needed)requestAnimationFrame(sync)});observer.observe(document.documentElement,{childList:true,subtree:true});window.SultanaCurrency={formatQAR:fmt,get:()=>currency,refresh:sync};
})();